<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\User\Application\Policy\Allow\Unlock;

use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Usecase\Unlock\UserUnlockAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedUnlockAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(UserUnlockAllowDecision $proposal): UserUnlockAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedUnlockAllow User");
        $span = $this->startSpan("Check IsAuthenticatedUnlockAllow User");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if ($userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedUnlock');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
